<script setup lang="ts">
import { computed, ref } from 'vue'
const dataset=ref('A')
const filled=ref(true)
const selected=ref(0)
const state=ref('ready')
const labels=['Jan','Feb','Mar','Apr','May','Jun']
const primary=computed(()=>dataset.value==='A'?[35,48,41,61,56,74]:dataset.value==='B'?[42,36,55,48,72,64]:[0,0,0,0,0,0])
const x=(i:number)=>40+i*48
const y=(v:number)=>170-v*1.4
const points=(values:number[])=>values.map((v,i)=>`${x(i)},${y(v)}`).join(' ')
const area=computed(()=>`M40,170 L${primary.value.map((v,i)=>`${x(i)},${y(v)}`).join(' L')} L280,170 Z`)
function reset(){dataset.value='A';filled.value=true;selected.value=0;state.value='ready'}
</script>
<template>
<section class="area-chart-demo" aria-label="Local area chart example"><p>Synthetic monthly units. Fill measures height above zero, not a cumulative total. Straight segments join observations.</p><div class="area-controls"><label>Dataset<select v-model="dataset"><option>A</option><option>B</option><option value="zero">All zero</option></select></label><label>Data state<select v-model="state"><option value="ready">Ready</option><option value="loading">Loading</option><option value="empty">Empty</option></select></label><label><input v-model="filled" type="checkbox">Show area fill</label><button type="button" @click="reset">Reset example</button></div><template v-if="state==='ready'"><div class="area-legend"><span>Single series: Primary units</span><span>Baseline: 0 units</span></div><svg :key="dataset+'-'+filled" viewBox="0 0 320 210" role="img" aria-label="Synthetic monthly units, January to June, fixed scale 0 to 100. Area returns to zero; exact values are in the table below."><g v-for="tick in [0,25,50,75,100]" :key="tick"><line x1="36" x2="292" :y1="y(tick)" :y2="y(tick)" class="area-grid"/><text x="4" :y="y(tick)+4">{{ tick }}</text></g><text v-for="(label,i) in labels" :key="label" :x="x(i)" y="194" text-anchor="middle">{{ label }}</text><path v-if="filled" :d="area" class="area-fill"/><polyline :points="points(primary)" class="area-primary"/><circle v-for="(v,i) in primary" :key="i" :cx="x(i)" :cy="y(v)" :r="selected===i?5:3" class="area-dot"/></svg><div role="group" aria-label="Select month" class="area-months"><button v-for="(label,i) in labels" :key="label" type="button" :aria-pressed="selected===i" @click="selected=i" @focus="selected=i">{{ label }}</button></div><p role="status">{{ labels[selected] }}: Primary {{ primary[selected] }} units.</p><table class="area-data"><caption>Exact sample values, dataset {{ dataset }}</caption><thead><tr><th scope="col">Month</th><th scope="col">Primary units</th></tr></thead><tbody><tr v-for="(label,i) in labels" :key="label"><th scope="row">{{ label }}</th><td>{{ primary[i] }}</td></tr></tbody></table></template><p v-else role="status" class="area-state">{{ state==='loading'?'Loading demonstration only; no request is running. Values are withheld.':'No sample observations in this state. Choose Ready to recover.' }}</p></section>
</template>
<style scoped>
.area-chart-demo{border:1px solid var(--vp-c-divider);border-radius:14px;padding:18px;margin:20px 0}.area-controls{display:flex;gap:14px;flex-wrap:wrap;align-items:end}.area-controls label{display:flex;gap:8px;align-items:center;font-size:13px}.area-chart-demo select{appearance:auto;padding:8px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg);color:var(--vp-c-text-1)}.area-chart-demo button{padding:6px 9px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft)}.area-chart-demo :is(button,select,input):focus-visible{outline:2px solid var(--vp-c-brand-1);outarea-offset:3px}.area-legend{display:flex;gap:16px;flex-wrap:wrap;margin-top:18px;font-size:12px}.area-chart-demo svg{display:block;width:100%;height:auto;max-height:330px;margin:16px 0;animation:area-chart-in .2s ease-out}.area-grid{stroke:var(--vp-c-divider);stroke-dasharray:3 4}.area-chart-demo svg text{fill:var(--vp-c-text-2);font-size:10px}.area-primary,.area-secondary{fill:none;stroke:var(--vp-c-brand-1);stroke-width:2.5}.area-fill{fill:var(--vp-c-brand-1);fill-opacity:.18;stroke:none}.area-dot{fill:var(--vp-c-brand-1);stroke:var(--vp-c-bg);stroke-width:1}.area-months{display:flex;gap:6px;flex-wrap:wrap}.area-months button[aria-pressed=true]{background:var(--vp-c-brand-soft);font-weight:700}.area-data{display:table!important;width:100%;font-size:12px}.area-data caption{text-align:left;padding:8px 0;color:var(--vp-c-text-2)}.area-data :is(td,th){padding:6px 8px!important}.area-state{padding:16px;background:var(--vp-c-bg-soft);border-radius:10px}@keyframes area-chart-in{from{opacity:.4}to{opacity:1}}@media(prefers-reduced-motion:reduce){.area-chart-demo svg{animation:none}}
</style>
